// Korea University Anam campus, science side (고려대 자연계) - a separate campus from the humanities package (user decision
// 2026-10-18). Data is generated by scripts/campuses/koreaScience/build-package.mjs from the pilot (pilot/korea-science):
// 23 destructible buildings + 5 sky / foot bridges (each its own destruction unit), a baked ground and the non-destructible
// context (OSM surroundings, 고려대로, parked cars, 안암병원 as a backdrop) that fades into the haze like the pilot preview.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, KS_PLACEMENTS, KS_BUILDING_BASE, KS_HEIGHT_GRIDS, KS_HEIGHT_RANGE_M, KS_ENV_IDS, KS_DISPLAY, KS_PROVENANCE } from './data.js';
import { KS_FOOTPRINTS } from './footprints.js?v=tape41';

const MODEL_IDS = Object.freeze(KS_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/koreaScience/${file}`, import.meta.url).href;

export const KOREA_SCIENCE = Object.freeze({
  id: 'koreaScience',
  meta: Object.freeze({ school: '고려대학교', campus: '안암캠퍼스 · 자연계', short: '고려대 자연계', modelNoun: '고려대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: KS_PLACEMENTS,
  approvedCount: KS_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['scienceLibrary', 'asanScience', 'hanaSquareNorth', 'engineering', 'newEngineering', 'hanaScienceA']),
  startBuildingId: 'scienceLibrary',
  // Start view turned 180° (user decision 2026-10-18): look past the library into the campus, not the car park.
  view: Object.freeze({ startTurn: Math.PI }),
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: KS_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: KS_HEIGHT_GRIDS, buildingBase: KS_BUILDING_BASE,
    source: 'Relative terrain estimate (SRTM + floor-link evidence, pilot/korea-science); not a survey' }),
  environment: Object.freeze({ provenance: KS_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); pre-works plaza, fill blocks, planting and heights estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: KS_ENV_IDS, castShadow: Object.freeze([]), fade: Object.freeze({ ...KS_DISPLAY.fade, colour: KS_DISPLAY.haze }), playMargin_m: 30,
      source: 'pilot/korea-science preview ground + context, baked' }),
  }),
  // Hospitals in the baked context stay non-destructible; invisible hit proxies from their walls give them the shield
  // reaction (src/protected-buildings.js).
  protected: Object.freeze({ contextMaterials: Object.freeze(['wall-hospital']) }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js, user decision 2026-10-18).
  hazardTape: Object.freeze({ footprints: KS_FOOTPRINTS }),
  scene: Object.freeze({
    background: KS_DISPLAY.haze, fog: Object.freeze({ color: KS_DISPLAY.haze, near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8a78', intensity: 1.3 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.9, position: Object.freeze([-100, 220, 120]), shadowSpan: 185 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: KS_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default KOREA_SCIENCE;
